<script lang="ts">
 import {interfaceLanguage} from '$lib/i18n/context.svelte';const ui=interfaceLanguage();
 import {Upload,X} from 'lucide-svelte';
 import {isMediaUrl} from './routing';
 let {label,value='',kind='image',onchange}:{label:string;value?:string;kind?:'image'|'audio'|'video'|'media';onchange:(value:string)=>void}=$props();
 let input:HTMLInputElement,error=$state('');
 const accept=$derived(kind==='image'?'image/png,image/jpeg,image/webp,image/gif':kind==='audio'?'audio/mpeg,audio/wav,audio/ogg,audio/mp4,audio/webm':kind==='video'?'video/mp4,video/webm':'video/mp4,video/webm,audio/mpeg,audio/wav,audio/ogg');
 async function upload(e:Event){const file=(e.currentTarget as HTMLInputElement).files?.[0];input.value='';if(!file)return;try{if(file.size>4_000_000)throw Error('El archivo puede tener hasta 4 MB. Para archivos mayores utiliza una URL.');if(!accept.split(',').includes(file.type))throw Error('Formato de archivo no admitido.');const url=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(Error('No se pudo leer el archivo.'));reader.readAsDataURL(file);});if(!isMediaUrl(url))throw Error('Archivo multimedia no válido.');onchange(url);error='';}catch(e){error=(e as Error).message;}}
</script>
<div class="media-field"><label>{label}<div class="row"><input aria-label={label} value={value.startsWith('data:')?'Archivo incorporado':value} readonly={value.startsWith('data:')} placeholder="https://… o /ruta-del-archivo" oninput={e=>onchange(e.currentTarget.value)}/><button aria-label={ui.text("Subir ")+label} title={ui.text("Subir archivo (hasta 4 MB)")} onclick={()=>input.click()}><Upload size={16}/></button>{#if value}<button aria-label={ui.text("Quitar ")+label} onclick={()=>onchange('')}><X size={16}/></button>{/if}</div></label><input class="hidden" bind:this={input} type="file" {accept} onchange={upload}/>{#if error}<p role="alert">{ui.text(error)}</p>{/if}</div>
<style>.media-field{margin:12px 0}.row{display:flex;gap:5px;margin-top:7px}.row input{width:100%;min-width:0;box-sizing:border-box;padding:9px;border:1px solid #d5dfce;border-radius:7px;color:#35502f;font:inherit}.row button{display:grid;place-items:center;flex:none;width:34px;border:1px solid #d5dfce;border-radius:7px;background:#fff;color:#35502f;cursor:pointer}.hidden{display:none}p{color:#a04d3a;font-size:11px}button:focus-visible,input:focus-visible{outline:2px solid #789557;outline-offset:2px}</style>
